package com.takenokoshi.overdriveae.main.mixin.injection;

import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.AbstractInsnNode;
import org.objectweb.asm.tree.InsnList;
import org.objectweb.asm.tree.VarInsnNode;
import org.spongepowered.asm.mixin.injection.InjectionPoint;
import org.spongepowered.asm.mixin.injection.struct.InjectionPointData;

import java.util.Collection;
/**
 * Generated by ChatGPT
 */
public class AfterStartedStore extends InjectionPoint {

    public AfterStartedStore(InjectionPointData data) {
        super(data);
    }

    @Override
    public boolean find(
            String desc,
            InsnList insns,
            Collection<AbstractInsnNode> nodes) {
        for (int i = 0; i < insns.size(); i++) {
            AbstractInsnNode insn = insns.get(i);

            // ISTORE 4 を探す
            if (insn instanceof VarInsnNode varInsn
                    && varInsn.getOpcode() == Opcodes.ISTORE
                    && varInsn.var == 4) {

                // 次の実命令を探す
                for (int j = i + 1; j < insns.size(); j++) {
                    AbstractInsnNode next = insns.get(j);

                    // LabelNode、FrameNode、LineNumberNode などを飛ばす
                    if (next.getOpcode() >= 0) {
                        nodes.add(next);
                        return true;
                    }
                }
            }
        }

        return false;
    }
}